import {
  type PrismaClient,
  type Prisma,
  type ModelOperator,
} from '@prisma/client'
import type { ModelAction } from './applyModel'
import { modelOperators } from './applyModel'

/**
 * Applies a model operation to a Prisma client instance
 * @param client Prisma client instance
 * @param modelName The name of the model to apply
 * @param operation The operation to perform
 * @returns The result of the operation
 */
export function applyModel(
  client: PrismaClient,
  modelName: string,
  operation: ModelOperator
): Promise<any> {
  const model = client._models[modelName]
  if (!model) {
    throw new Error(`Model ${modelName} not found in Prisma client`)
  }

  const modelMethod = modelOperators[operation]
  if (!modelMethod) {
    throw new Error(`Invalid operation: ${operation}`)
  }

  return modelMethod(client, modelName)
}

