export async function GET(request: Request) {
  const url = new URL(request.url)
  const cursor = url.searchParams.get('cursor')
  const take = Number(url.searchParams.get('take') ?? '20')

output:
  const orderBy = url.searchParams.get('orderBy') as 'id' | 'createdAt' | 'title'

  const where = {
    deletedAt: null,
  }

  if (cursor) {
    where.id = { gt: cursor }
  }

  const takeCount = take + 1

  const [items, total] = await Promise.all([
    prisma.post.findMany({
      where,
      orderBy: { [orderBy!]: 'asc' },
      take: takeCount,
      skip: 0,
      include: {
        author: { select: { name: true } },
        category: true,
        coverImage: true,
        tags: { include: { tag: true } },
        _count: { select: { comments: true } },
      },
    }),
    prisma.post.count({ where }),
  ])

  const hasMore = items.length > takeCount
  const itemsWithId = hasMore ? items.slice(0, takeCount) : items

  return NextResponse.json({
    posts: itemsWithId,
    total,
    cursor: items.length > 0 ? items[items.length - 1].id : null,
  })
}
