      setIsDarkMode(true)
      document.documentElement.classList.add('dark')
    }

    const handlePrefersLight = () => {
      setIsDarkMode(false)
      document.documentElement.classList.remove('dark')
    }

    window.matchMedia('(prefers-color-scheme: dark)').addEventListener('change', handlePrefersDark)
    window.matchMedia('(prefers-color-scheme: light)').addEventListener('change', handlePrefersLight)

    return () => {
      window.matchMedia('(prefers-color-scheme: dark)').removeEventListener('change', handlePrefersDark)
