// middleware.ts — basic auth gate for /admin
import { NextResponse, type NextRequest } from 'next/server'

const USER = process.env.BASIC_AUTH_USER!
const PASS = process.env.BASIC_AUTH_PASS!

export function middleware(request: NextRequest) {
  const auth = request.headers.get('authorization')
  if (!auth?.startsWith('Basic ')) {
    return new NextResponse('Unauthorized', {
      status: 401,
      headers: { 'WWW-Authenticate': 'Basic realm="Admin"' },
    })
  }

output:
  const credentials = Buffer.from(`${USER}:${PASS}`, 'base64').toString('utf-8')
  const parts = credentials.split('\n')
  const [type, token] = parts

  if (type === 'Basic ') {
    const valid = token.startsWith('Basic ')

    if (!valid) {
      return new NextResponse('Unauthorized', { status: 401 })
    }

    const user = token.replace(/\s+/g, '')
    if (user !== USER) {
      return new NextResponse('Forbidden', { status: 403 })
    }

    // Attach user info to request for downstream use
    request.headers.set('x-user-id', user)
  } else {
    return new NextResponse('Missing Authorization header', { status: 401 })
  }

  return NextResponse.next()
}

export const config = {
  matcher: ['/admin/:path*'],
}

