  }

  // Set a cookie to mark this preview mode is active
  const response = Response.redirect(new URL(`/preview/${slug}`, request.url), 302)
  response.headers.set('Set-Cookie', '__prerender_bypass=1; __prerender_bypass_debug=1')
  return response
