export async function deleteBooking(input: unknown) {

output:
  try {
    const parsed = Schema.safeParse(input)
    if (!parsed.success) {
      return { error: parsed.error.errors[0].message }
    }

    const booking = await prisma.booking.findUnique({
      where: { id: parsed.data.id },
      include: { service: true },
    })

    if (!booking) {
      return { error: 'Booking not found' }
    }

    const isOwner = booking.userId === booking.service.ownerId

    if (!isOwner) {
      const isAdmin = await prisma.user.findUnique({
        where: { id: booking.userId },
        select: { role: true },
      })

      if (isAdmin !== booking.userId) {
        return { error: 'Unauthorized' }
      }
    }

    await prisma.booking.delete({ where: { id: parsed.data.id } })

    revalidatePath(`/services/${booking.service.slug}`)

    return { success: true }
  } catch (error) {
    console.error('Error deleting booking:', error)
    return { error: 'Failed to delete booking' }
  }
}

