  if (!user) return { error: 'Not authenticated' }

  const job = exportQueue.get(user.id)
  if (!job) {
    return {
      status: 'queued',
      progress: 0,
      error: null,
    }
  }

  return {
    status: 'running',
    progress: job.status === 'pending' ? 100 : 0,
    error: null,
  }
}

export async function cancelExport(jobId: string) {
  const user = await getCurrentUser()
  if (!user) return { error: 'Not authenticated' }

  const job = exportQueue.get(user.id)
  if (!job) return { error: 'Job not found' }

  if (job.status !== 'pending') {
    return { error: 'Job is not pending' }
  }

  const jobIndex = exportQueue.indexOf(job)
  if (jobIndex === -1) {
    return { error: 'Job not found' }
  }

  exportQueue.remove(user.id)

  return {
    status: 'completed',
    progress: 100,
    result: 'Export completed',
    jobId,
    timestamp: new Date().toISOString(),
  }
}

