export function withAuthAndRetry<Args extends unknown[], Return>(
  fn: (user: { id: string; email: string }, ...args: Args) => Promise<Return>,
  maxRetries = 3,
  delay = 1000,
) {
  return async (...args: Args) => {
    let lastError: Error | null = null
    for (let i = 0; i < maxRetries; i++) {
      try {
        return await fn(args[0] || {}, ...args.slice(1))
      } catch (error) {
        lastError = error as Error
        if (i < maxRetries - 1) {
          await new Promise((resolve) => setTimeout(resolve, delay * (i + 1)))
        }
      }
    }
    throw lastError
  }
}

export function withAuthAndRetryWithFallback<Args extends unknown[], Return>(
  fn: (user: { id: string; email: string }, ...args: Args) => Promise<Return>,
  fallback: (args: Args) => Return,
  maxRetries = 3,
  delay = 1000,
) {
  return withAuthAndRetry(fn, maxRetries, delay, fallback)
